"""Hand / finger ligament rows, flexor pulleys, extensor mechanism, and fascial passages of the limbs."""
from rows_common import P, S

# =================================================================== FINGER COLLATERAL LIGAMENTS - owner example (proper + accessory + volar plate)
_PIP = "collateral_interphalangeal_ligaments_of_hand"   # Z-Anatomy structure id (no own-body mesh; the data layer has no PIP/DIP record)
P(_PIP, "pip_proper_collateral", "ligament_component", "PIP proper collateral ligament", "Arises widely from dorsal and proximal to the fovea on the side of the proximal phalangeal head and inserts along most of the side of the base of the middle phalanx; stout; fibres parallel to the middle phalanx in all joint positions (differs from most line drawings).",
  ["allison2005", "pang2018"], cls="ligament", ev="microscope dissection n=8 PIP joints + 2 histology", setid="finger_collateral.pairs", z=["zan_collateral_interphalangeal_ligaments_of_hand_{s}"], geom=dict(rule="z_part_mesh"),
  note="Z-Anatomy has one mesh per hand for ALL interphalangeal collaterals (proper + accessory not separated): the position is the pooled centroid.")
P(_PIP, "pip_accessory_collateral", "ligament_component", "PIP accessory collateral ligament", "Less substantial; lies between the proper collateral ligament and the volar plate; suspends the plate laterally with the A3 pulley; contains the assemblage nuclei (mechanoreceptors).",
  ["allison2005", "pang2018", "lee2013pp", "chikenji2010"], cls="ligament", ev="dissection; 3-D reconstruction n=16; immunohistochemistry n=12", setid="finger_collateral.pairs")
P("palmar_interphalangeal_ligaments", "pip_volar_plate_distal_fibrous", "ligament_component", "PIP volar (palmar) plate: distal fibrous portion", "Distal fibrous portion anchoring to the base of the middle phalanx.", ["lee2013pp", "bowers1980"], cls="ligament", ev="3-D dissection n=16; n=60", setid="finger_collateral.pairs",
  z=["zan_palmar_interphalangeal_ligaments_{s}"], geom=dict(rule="z_part_mesh"))
P("palmar_interphalangeal_ligaments", "pip_volar_plate_proximal_membranous_checkrein", "ligament_component", "PIP volar plate: proximal membranous portion + check-rein ligaments", "Proximal membranous portion continuous with the bilateral check-rein ligaments; proximal attachments distinctive, distal attachments variable (Bowers).", ["lee2013pp", "bowers1980"], cls="ligament", ev="3-D dissection n=16; n=60")
P(_PIP, "dip_accessory_collateral", "ligament_component", "DIP accessory collateral ligament", "Contains the assemblage nuclei of the DIP joint; the C3 pulley contains their proximal region, the A5 pulley the middle and distal parts.", ["chikenji2011"], cls="ligament", ev="immunohistochemistry n=12 index DIP", setid="finger_collateral.pairs")
P(_PIP, "dip_proper_collateral", "ligament_component", "DIP proper collateral ligament", "By analogy with the PIP joint (proper + accessory + volar plate); not described in the cited DIP paper.", ["pang2018", "gray42"], ver="unverified", cls="ligament", ev="textbook / analogy", setid="finger_collateral.pairs")
S("finger_collateral.pairs", _PIP, "ligament_component", "Interphalangeal collateral system: components", [(3, "pang2018", "proper collateral, accessory collateral, volar plate (PIP)")])
_MCP = "finger_mcp_collateral_and_plate_complex"
P(_MCP, "mcp_proper_collateral", "ligament_component", "MCP proper collateral ligament (cord)", "Proper (cord) collateral ligament of the finger MCP joint, taut in flexion. NOT verified by a PubMed anatomy abstract in this search (only thumb MCP collaterals were).", ["gray42"], ver="unverified", cls="ligament", ev="textbook",
  z=["zan_collateral_metacarpophalangeal_ligaments_{s}"], geom=dict(rule="z_part_mesh"))
P(_MCP, "mcp_accessory_collateral", "ligament_component", "MCP accessory collateral ligament (fan)", "Accessory collateral ligament inserting into the volar plate.", ["gray42"], ver="unverified", cls="ligament", ev="textbook")
P(_MCP, "mcp_volar_plate", "ligament_component", "MCP volar (palmar) plate", "Fibrocartilaginous plate attached to the base of the proximal phalanx.", ["gray42"], ver="unverified", cls="ligament", ev="textbook")
P("thumb_mcp_ucl", "proper_collateral", "ligament_component", "Thumb MCP ulnar collateral ligament: proper", "Origin centre 4.2 mm from the dorsal surface and 5.3 mm from the articular surface of the metacarpal head; phalangeal insertion centre 2.8 mm from the volar surface and 3.4 mm from the articular surface (n=18).", ["carlson2012"], cls="ligament", ev="cadaver n=18 UCL", setid="thumb_ucl.parts")
P("thumb_mcp_ucl", "accessory_collateral", "ligament_component", "Thumb MCP ulnar collateral ligament: accessory", "A complete UCL tear involves both the proper and the accessory ligaments.", ["patel2019"], cls="ligament", ev="biomechanics n=8", setid="thumb_ucl.parts")
S("thumb_ucl.parts", "thumb_mcp_ucl", "ligament_component", "Thumb UCL: components", [(2, "patel2019", "proper + accessory")])
P("thumb_mcp_rcl", "proper_collateral", "ligament_component", "Thumb MCP radial collateral ligament: proper", "Origin centre 3.5 mm from the dorsal surface and 3.3 mm from the articular surface; insertion 2.8 mm from the volar surface, 2.6 mm from the articular surface (n=18).", ["carlson2012"], cls="ligament", ev="cadaver n=18 RCL")

# =================================================================== FLEXOR TENDON PULLEYS
for nm, ds in [("palmar_aponeurosis_pulley", "Palmar aponeurosis pulley (described by Manske and Lesker)."), ("a1", "First annular pulley (A1)."), ("a2", "Second annular pulley (A2)."), ("a3", "Third annular pulley (A3); at the PIP joint with C1 proximal."),
               ("a4", "Fourth annular pulley (A4)."), ("a5", "Fifth annular pulley (A5); over the DIP joint, contains the middle and distal regions of the DIP assemblage nuclei."), ("c1", "First cruciform pulley (C1); proximal region of the PIP assemblage nuclei."), ("c2", "Second cruciform pulley (C2)."), ("c3", "Third cruciform pulley (C3); proximal region of the DIP assemblage nuclei.")]:
    P("flexor_tendon_pulley_system_hand", nm, "ligament_component", ds, ds + " Doyle 1988: 61 fingers; palmar aponeurosis pulley, five annular and three cruciform pulleys.", ["doyle1988"] + (["chikenji2010", "chikenji2011"] if nm in ("a3", "a5", "c1", "c3") else []), cls="tendon", ev="fresh cadaver fingers n=61", setid="flexor_pulleys.parts",
      z=(["zan_cruciform_part_of_fibrous_sheath_of_digit_of_hand_{s}"] if nm.startswith("c") else []))
S("flexor_pulleys.parts", "flexor_tendon_pulley_system_hand", "ligament_component", "Finger flexor pulley system: pulleys", [(9, "doyle1988", "palmar aponeurosis pulley + 5 annular + 3 cruciform"), (4, "zafonte2014", "thumb pulley system: 4 components, not the classical 3")])
P("flexor_tendon_pulley_system_hand", "thumb_pulleys_four", "ligament_component", "Thumb pulley system: four components", "The thumb pulley system has 4 constituents, in contrast to the classic teaching of 3.", ["zafonte2014"], cls="tendon", ev="review", setid="flexor_pulleys.parts")

# =================================================================== INTRINSICS / EXTENSOR MECHANISM
for nm in ("dorsal_interossei_hand", "palmar_interossei"):
    pct = "75 %" if nm.startswith("dorsal") else "38 %"
    P(nm, "multiple_heads", "head_belly", "Additional heads (more than one head)", f"{pct} of these interossei had more than one head (14 fresh hands); up to three heads, each with a different distal destination.", ["eladou2002"], ev="cadaver n=14 hands", var=pct)
    P(nm, "insertion_bone", "insertion_point", "Distal insertion: bone (base of the proximal phalanx)", "Interossei insert on bone as well as the extensor apparatus (and, per Zancolli, the volar plate).", ["eladou2002"], ev="cadaver n=14 hands")
    P(nm, "insertion_extensor_apparatus", "insertion_point", "Distal insertion: extensor apparatus", "Insertion onto the extensor apparatus (lateral band / hood).", ["eladou2002"], ev="cadaver n=14", related=["extensor_hood"])
    P(nm, "insertion_volar_plate", "insertion_point", "Distal insertion: volar plate (assemblage nucleus)", "Additional insertion on the volar plate, described by Zancolli; palmar interossei too may insert on bone and volar plate.", ["eladou2002"], ev="cadaver n=14")
P("extensor_digitorum", "intertendinous_connection_2nd_space", "ligament_component", "Intertendinous connection, 2nd intermetacarpal space (usually type 1 filamentous)", "Most common pattern: type 1 (filamentous band).", ["hirai2001"], ev="cadaver n=548 limbs", var="type 1 most common", cls="muscle")
P("extensor_digitorum", "intertendinous_connection_3rd_space", "ligament_component", "Intertendinous connection, 3rd intermetacarpal space (usually type 3r)", "Most common: type 3r (tendinous, r-shaped).", ["hirai2001"], ev="cadaver n=548", var="type 3r", cls="muscle")
P("extensor_digitorum", "intertendinous_connection_4th_space", "ligament_component", "Intertendinous connection, 4th intermetacarpal space (usually type 3y)", "Most common: type 3y (tendinous, y-shaped).", ["hirai2001"], ev="cadaver n=548", var="type 3y", cls="muscle")
P("extensor_digiti_minimi", "two_slips", "insertion_point", "Extensor digiti minimi tendon: two slips", "The extensor digiti minimi tendon consisted of 2 slips (most common pattern).", ["hirai2001"], ev="cadaver n=548")
P("extensor_hood", "oblique_retinacular_ligament", "ligament_component", "Oblique retinacular ligament (Landsmeer)", "Functionally present in only 40-50 % of fingers (over 90 % on the ulnar side of the ring finger); when absent a proximal osteocapsular ligament is present.", ["shrewsbury1977"], cls="tendon", ev="dissection n=64 fingers", var="40-50 %")
P("abductor_pollicis_longus", "tendon_slips", "insertion_point", "Tendon slips (accessory slips)", "Single tendon in 20/48 forearms, double 9, triple 8, quadruple 5, five slips in 6; 93 % reach the first metacarpal, 7 % the trapezium. Another series: accessory slips in 18/20 hands (90 %), 3-6 slips; mean three slips in 6 forearms.", ["deshmukh2023", "lamas2026", "thandoni2024"],
  ev="cadaver n=48; n=20; n=6", var="1-5 slips", anchor=dict(bone="metacarpal_1", landmark="base of first metacarpal (93 %); trapezium (7 %)"))
P("first_dorsal_compartment", "separate_epb_subcompartment", "fascial_passage", "First dorsal compartment: separate EPB subcompartment", "A separate extensor pollicis brevis compartment was present in 4 of 6 forearms; the superficial radial nerve crossed the compartment in 2.", ["thandoni2024"], cls="tendon", ev="cadaver n=6",
  passes=dict(kind="tendon", traversing=["abductor_pollicis_longus", "extensor_pollicis_brevis"], through="first dorsal compartment of the extensor retinaculum"))

# =================================================================== FASCIAL PASSAGES (limbs)
for k, tends in [(1, "abductor pollicis longus, extensor pollicis brevis"), (2, "extensor carpi radialis longus and brevis"), (3, "extensor pollicis longus"), (4, "extensor digitorum, extensor indicis"), (5, "extensor digiti minimi"), (6, "extensor carpi ulnaris")]:
    P("extensor_retinaculum", f"compartment_{k}", "fascial_passage", f"Extensor retinaculum compartment {k}: {tends}", f"One of the 6 tunnels of the extensor retinaculum (septal attachments on the radius measured; septum 1/2 largest, 3/4 smallest). The tendon content per compartment is textbook, not stated in the abstract.", ["iwamoto2006", "gray42"], ver="unverified",
      cls="fascia", ev="cadaver n=34 wrists (count of 6 verified)", passes=dict(kind="tendon", traversing=[], traversing_text=tends, through="extensor retinaculum of the wrist"), z=["zan_extensor_retinaculum_of_wrist_{s}"] if k == 1 else [])
P("flexor_retinaculum", "carpal_tunnel_passage", "fascial_passage", "Carpal tunnel: median nerve and long finger flexor tendons pass beneath the transverse carpal ligament", "Retinaculum has three segments (proximal = deep forearm fascia, transverse carpal ligament, distal aponeurosis); tunnel width at the hook of the hamate 20 mm (24 mm proximal, 25 mm distal). The nerve and tendon content is textbook.", ["cobb1993", "gray42"], ver="unverified", cls="fascia", ev="cadaver n=26 (retinaculum limits verified)",
  passes=dict(kind="nerve+tendon", traversing=["median_n"], traversing_text="median nerve; FDS, FDP, FPL tendons", through="flexor retinaculum (transverse carpal ligament)"), related=["median_n"], geom=dict(rule="passage_contact", nerve="median_n", fascia="flexor_retinaculum"))
P("antebrachial_fascia", "palmar_cutaneous_branch_median_nerve", "fascial_passage", "Palmar cutaneous branch of the median nerve (exits the forearm fascia, runs near the thenar crease)", "The palmar cutaneous branch lies on average 0-2 mm radial to the thenar crease and about 5 mm radial to the interthenar depression (25 hands). The piercing of the antebrachial fascia proximal to the wrist is textbook, not stated in the abstract.", ["watchmaker1996", "gray42"], ver="unverified", cls="fascia", ev="cadaver n=25 (course verified)",
  passes=dict(kind="nerve", traversing=["median_n"], traversing_text="palmar cutaneous branch of the median nerve", through="antebrachial fascia / flexor retinaculum roof"))
P("antebrachial_fascia", "superficial_radial_nerve_exit", "fascial_passage", "Superficial branch of the radial nerve becomes subcutaneous between brachioradialis and ECRL tendons", "Becomes subcutaneous a mean 9.0 cm proximal to the radial styloid, passing between the tendons of brachioradialis and extensor carpi radialis longus; branches a mean 5.1 cm proximal to the styloid.", ["abrams1992"], cls="fascia", ev="cadaver n=20",
  passes=dict(kind="nerve", traversing=["radial_n_superficial_branch"], through="antebrachial fascia (between BR and ECRL tendons)"), related=["radial_n_superficial_branch"])
P("arcade_of_frohse", "pin_entry_supinator", "fascial_passage", "Posterior interosseous nerve enters the supinator under the arcade of Frohse", "Superior border of the superficial supinator layer tendinous (arcade of Frohse) in 40 of 46 limbs (87 %); superomedial margin of ECRB tendinous in 36/46; fibrous adhesions to the capsule in 23/46.", ["konjengbam2004"], cls="fascia", ev="cadaver n=46", var="87 %",
  passes=dict(kind="nerve", traversing=["posterior_interosseous_n"], through="arcade of Frohse (supinator)"), related=["posterior_interosseous_n", "supinator"], geom=dict(rule="passage_contact", nerve="posterior_interosseous_n", fascia="supinator"))
P("cubital_tunnel_retinaculum", "ulnar_nerve_roof", "fascial_passage", "Ulnar nerve beneath the cubital tunnel retinaculum", "Fibrous band ~4 mm wide from the medial epicondyle to the olecranon forming the proximal roof; absent in 1 of 27 (type 0), lax in extension and taut in flexion in 17 (type Ia).", ["odriscoll1991"], cls="fascia", ev="cadaver n=27", var="types 0 / Ia / Ib / ...",
  passes=dict(kind="nerve", traversing=["ulnar_n"], through="cubital tunnel retinaculum"), related=["ulnar_n"], geom=dict(rule="passage_contact", nerve="ulnar_n", fascia="cubital_tunnel_retinaculum"))
P("arcade_of_struthers", "ulnar_nerve_passage", "fascial_passage", "Ulnar nerve under the arcade of Struthers (internal brachial ligament)", "A compressive arcade was found in 67 of 197 (34 %) patients undergoing ulnar nerve transposition (51 % in revision); all had an internal brachial ligament running below the nerve.", ["elmaraghi2024"], cls="fascia", ev="surgical series n=197", var="34 %",
  passes=dict(kind="nerve", traversing=["ulnar_n"], through="arcade of Struthers / medial intermuscular septum"), related=["ulnar_n", "medial_intermuscular_septum"])
P("crural_fascia", "superficial_fibular_nerve_exit", "fascial_passage", "Superficial fibular (peroneal) nerve pierces the crural fascia", "In 85 legs the nerve or its branches passed through the crural fascia 3-18 cm proximal to the lateral malleolus; in 73 % it ran in the lateral compartment from origin to exit, 14 % crossed from the lateral to the anterior compartment, 12 % divided in two; emerges between peroneus longus and EDL at a highly variable level (sonography n=60 legs).", ["adkison1991", "canella2009"],
  cls="fascia", ev="cadaver n=85 legs; sonography n=60", var="73 / 14 / 12 %", passes=dict(kind="nerve", traversing=["superficial_fibular_n"], through="crural fascia (lateral/anterior compartment septum)"), related=["superficial_fibular_n"], geom=dict(rule="passage_contact", nerve="superficial_fibular_n", fascia="crural_fascia"))
P("crural_fascia", "medial_perforating_veins", "fascial_passage", "Medial perforating veins piercing the deep (crural) fascia", "40 limbs: 552 medial perforators (mean 13.8); 52 % direct (superficial to deep), 41 % indirect muscle perforators; Cockett II/III groups 7-9 cm and 10-12 cm above the ankle; three paratibial groups 18-22, 23-27, 28-32 cm; paratibial perforators need an incision of the paratibial deep fascia.", ["mozes1996"],
  cls="fascia", ev="cadaver n=40 limbs", passes=dict(kind="vein", traversing=["perforator_veins", "posterior_tibial_v"], through="crural (deep) fascia"), related=["perforator_veins"])
P("fascia_lata", "saphenous_opening", "fascial_passage", "Saphenous opening (fossa ovalis): great saphenous vein into the femoral vein", "The long saphenous vein runs in a fascial compartment; its fascial relationships are described by Caggiati 1999/2000; the existence of the opening and its transmitted structures is textbook.", ["caggiati1999", "caggiati2000", "gray42"], ver="unverified", cls="fascia", ev="textbook (Caggiati: title/abstract of fascial relations only)",
  passes=dict(kind="vein", traversing=["great_saphenous_v"], through="fascia lata (cribriform fascia)"), related=["great_saphenous_v"])
P("flexor_retinaculum_ankle", "tarsal_tunnel_passage", "fascial_passage", "Tarsal tunnel: tibial nerve and flexor tendons beneath the flexor retinaculum", "68 feet: bifurcation of the tibial nerve into medial and lateral plantar nerves within the tunnel in 93 % (proximal to it in 7 %); nine patterns of calcaneal branching.", ["havel1988"], cls="fascia", ev="cadaver n=68 feet", var="93 / 7 %",
  passes=dict(kind="nerve+tendon", traversing=["tibial_n"], traversing_text="tibial nerve; tibialis posterior, FDL, FHL tendons", through="flexor retinaculum of the ankle"), related=["tibial_n", "tibialis_posterior"], geom=dict(rule="passage_contact", nerve="tibial_n", fascia="flexor_retinaculum_ankle"))
P("piriformis", "sciatic_nerve_infrapiriform_passage_variants", "fascial_passage", "Sciatic nerve relation to piriformis (gap and variants)", "Piriformis and/or sciatic nerve anomalies range from 1.5 % to 35.8 % in dissected specimens (meta-analysis); the specific variant types (nerve through or above the muscle belly) are textbook and not itemised in the abstract.", ["smoll2010"], ev="systematic review / meta-analysis",
  passes=dict(kind="nerve", traversing=["sciatic_n"], through="greater sciatic foramen (infrapiriform gap)"), related=["sciatic_n"], var="1.5-35.8 %", geom=dict(rule="passage_contact", nerve="sciatic_n", fascia="piriformis"))
P("rectus_sheath", "thoracoabdominal_nerves_and_deep_inferior_epigastric_plexus", "fascial_passage", "Segmental nerves and the deep inferior epigastric 'rectus sheath plexus' in the sheath", "The thoracolumbar nerves travel as multiple mixed segmental nerves that communicate widely in the transversus abdominis plane and in a rectus sheath plexus running with the deep inferior epigastric artery; rectus abdominis is supplied by T6-L1 with a constant L1 branch; the umbilicus always by a T10 branch.", ["rozen2008"],
  cls="fascia", ev="cadaver n=20 hemi-abdominal walls", passes=dict(kind="nerve+vessel", traversing=["thoracoabdominal_n_t7_rectus_abdominis_branch", "thoracoabdominal_n_t8_rectus_abdominis_branch", "thoracoabdominal_n_t9_rectus_abdominis_branch", "thoracoabdominal_n_t10_rectus_abdominis_branch", "thoracoabdominal_n_t11_rectus_abdominis_branch", "subcostal_n_rectus_abdominis_branch"],
  traversing_text="deep inferior epigastric artery", through="rectus sheath"), related=["rectus_abdominis"])
P("linea_alba", "umbilical_ring", "fascial_passage", "Umbilical ring: passage of the obliterated umbilical structures", "Round hepatic (teres) ligament, median and medial umbilical ligaments attach at/pass the umbilical ring; ring classified into five types; the umbilical fascia is a continuation of the umbilicovesicular fascia in the authors' view; hernia incidence was 25 % and all hernia cases lacked the umbilical fascia.", ["fathi2012"],
  cls="fascia", ev="cadaver n=24", var="5 types", passes=dict(kind="ligament", traversing=[], traversing_text="round ligament of liver, median umbilical ligament, medial umbilical ligaments", through="umbilical ring (linea alba)"))
P("rectus_abdominis", "arcuate_line_inferior_epigastric_entry", "fascial_passage", "Arcuate line: lower end of the posterior sheath where the inferior epigastric vessels meet the muscle", "The arcuate line marks the lower extent of the posterior rectus sheath; the deep inferior epigastric vessels enter the rectus sheath behind the muscle at this level (textbook; the vessels are not mentioned in the cited abstract).", ["mwachaka2010", "gray42"], ver="unverified", ev="textbook; arcuate line position verified",
  passes=dict(kind="vessel", traversing=[], traversing_text="deep inferior epigastric vessels", through="posterior rectus sheath / arcuate line"), related=["rectus_sheath"])
